function ready(iframe: HTMLIFrameElement) {
  frame.current = iframe;
  const doc = iframe.contentDocument;
  if (!doc) return;
  sync(doc);
  if (boundDocuments.current.has(doc)) return;
  boundDocuments.current.add(doc);

  doc.addEventListener('click', (event) => {
    const target = event.target as Element | null;
    const videoBtn = target?.closest<HTMLElement>('[data-studio-video-target]');
    if (videoBtn && videoBtn.dataset.studioVideoTarget) {
      event.preventDefault();
      event.stopPropagation();
      const targetId = videoBtn.dataset.studioVideoTarget;
      if (
        pageRef.current.fields.some((f) => f.id === targetId) &&
        doc.querySelector(`video[data-studio-field="${targetId}"]`)
      ) {
        setSelected(targetId);
      }
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    const node = target?.closest<HTMLElement>('[data-studio-field]');
    if (node && node.dataset.studioField) {
      setSelected(node.dataset.studioField);
    }
  });

  doc.addEventListener('submit', (event) => event.preventDefault());

  for (const node of doc.querySelectorAll<HTMLElement>('[data-studio-field]')) {
    node.tabIndex = 0;
    node.setAttribute('role', 'button');
    node.setAttribute(
      'aria-label',
      `Modifier ${node.textContent?.trim().slice(0, 70) || 'cet élément'}`
    );
    node.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        if (node.dataset.studioField) setSelected(node.dataset.studioField);
      }
    });
  }

  const win = doc.defaultView;
  if (!win) return;

  videoCleanupsRef.current.forEach((fn) => fn());
  videoCleanupsRef.current = [];

  let disposed = false;
  const isStale = () => disposed || frame.current?.contentDocument !== doc || !doc.defaultView;

  const entries: { video: HTMLVideoElement; button: HTMLButtonElement }[] = [];

  for (const oldBtn of doc.querySelectorAll('[data-studio-video-affordance]')) {
    oldBtn.remove();
  }

  for (const video of doc.querySelectorAll<HTMLVideoElement>('video[data-studio-field]')) {
    const fieldId = video.dataset.studioField;
    if (!fieldId) continue;

    const btn = doc.createElement('button');
    btn.type = 'button';
    btn.dataset.studioVideoTarget = fieldId;
    btn.dataset.studioVideoAffordance = 'true';
    btn.setAttribute('aria-label', 'Modifier la vidéo');
    btn.innerHTML =
      '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="flex-shrink:0"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg><span>Modifier la vidéo</span>';
    btn.style.position = 'fixed';
    btn.style.zIndex = '2147483647';
    btn.style.display = 'inline-flex';
    btn.style.alignItems = 'center';
    btn.style.gap = '5px';
    btn.style.background = '#087f68';
    btn.style.color = '#ffffff';
    btn.style.border = '1px solid #066352';
    btn.style.borderRadius = '4px';
    btn.style.padding = '4px 8px';
    btn.style.fontFamily =
      'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
    btn.style.fontSize = '12px';
    btn.style.fontWeight = '600';
    btn.style.lineHeight = '1';
    btn.style.boxShadow = '0 2px 4px rgba(0,0,0,0.2)';
    btn.style.cursor = 'pointer';
    btn.style.userSelect = 'none';
    btn.style.pointerEvents = 'auto';

    btn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (
        pageRef.current.fields.some((f) => f.id === fieldId) &&
        doc.querySelector(`video[data-studio-field="${fieldId}"]`)
      ) {
        setSelected(fieldId);
      }
    });

    btn.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        event.stopPropagation();
        if (
          pageRef.current.fields.some((f) => f.id === fieldId) &&
          doc.querySelector(`video[data-studio-field="${fieldId}"]`)
        ) {
          setSelected(fieldId);
        }
      }
    });

    const container = doc.body || doc.documentElement;
    if (container) {
      container.appendChild(btn);
      entries.push({ video, button: btn });
    }
  }

  const updatePositions = () => {
    if (isStale()) return;
    const vpH = win.innerHeight || doc.documentElement.clientHeight || 600;
    const vpW = win.innerWidth || doc.documentElement.clientWidth || 800;
    for (const { video, button } of entries) {
      if (!doc.contains(video)) {
        button.style.display = 'none';
        continue;
      }
      const rect = video.getBoundingClientRect();
      if (
        rect.width === 0 ||
        rect.height === 0 ||
        rect.bottom <= 0 ||
        rect.top >= vpH ||
        rect.right <= 0 ||
        rect.left >= vpW
      ) {
        button.style.display = 'none';
        continue;
      }
      const pad = 6;
      const btnHeight = 26;
      const btnWidth = 130;
      const top = Math.max(pad, Math.min(rect.top + pad, vpH - btnHeight - pad));
      const left = Math.max(pad, Math.min(rect.left + pad, vpW - btnWidth - pad));
      button.style.display = 'inline-flex';
      button.style.top = `${top}px`;
      button.style.left = `${left}px`;
    }
  };

  updatePositions();

  win.addEventListener('scroll', updatePositions, { passive: true, capture: true });
  win.addEventListener('resize', updatePositions, { passive: true });

  let ro: ResizeObserver | null = null;
  if (typeof ResizeObserver !== 'undefined') {
    ro = new ResizeObserver(() => updatePositions());
    for (const { video } of entries) {
      ro.observe(video);
    }
  }

  const cleanup = () => {
    disposed = true;
    win.removeEventListener('scroll', updatePositions, true);
    win.removeEventListener('resize', updatePositions);
    if (ro) {
      ro.disconnect();
      ro = null;
    }
    for (const { button } of entries) {
      button.remove();
    }
    entries.length = 0;
  };

  win.addEventListener('pagehide', cleanup, { once: true });
  win.addEventListener('unload', cleanup, { once: true });

  videoCleanupsRef.current.push(cleanup);
}
